first=2016
def backtest(tri,cut=2022):
    # truncate to valuations <= cut; volume-weighted incurred factors from that data; project AYs to age 10 with no tail
    t={ay:v[:cut-ay+1] for ay,v in tri.items() if ay<=cut}
    f={}
    for a in range(1,10):
        num=den=0
        for ay,v in t.items():
            if len(v)>a: num+=v[a]; den+=v[a-1]
        if den: f[a]=num/den
    ind=act=0; base=0
    for ay,v in t.items():
        if ay>2021: continue
        x=v[-1]
        for k in range(len(v),10): x*=f.get(k,1.0)
        ind+=x-v[-1]; act+=tri[ay][-1]-v[-1]; base+=v[-1]
    return ind/base*100, act/base*100
print(f"{'':38s} yr2 chg 2016-21 avg | 2022 2023 2024 yr2 | first->latest AY16-21 | back-test from end-2022: indicated vs actual, % of carried AY16-21")
